// AUTO-GENERATED brand asset. The "Trova" logotype pre-rendered from the
// Playfair Display Bold-Italic face (the TTF behind theme fonts.wordmark),
// embedded as a base64 data URI on purpose: a res/drawable PNG gets collapsed
// to opaque grayscale by the release aapt2 PNG optimizer (alpha baked into
// luminance -> a black box). A data URI is decoded from the JS bundle at
// runtime, so the resource pipeline never touches it and the alpha survives.
// Regenerate: render assets/trova-wordmark.png, then re-run the generator.
export const TROVA_WORDMARK_URI =
  'data:image/png;base64,';
export const TROVA_WORDMARK_ASPECT = 800 / 270;
